function SliderCanalRgb({
  label,
  valor,
  corFinal,
  onChange,
}: {
  label: 'R' | 'G' | 'B';
  valor: number;
  corFinal: string;
  onChange: (valor: number) => void;
}) {
  const [largura, setLargura] = useState(1);
  const atualizarPorPosicao = (x: number) => {
    onChange(limitarCanal((x / largura) * 255));
  };
  const panResponder = React.useMemo(
    () => PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: event => atualizarPorPosicao(event.nativeEvent.locationX),
      onPanResponderMove: event => atualizarPorPosicao(event.nativeEvent.locationX),
    }),
    [largura]
  );
  const posicao = `${(limitarCanal(valor) / 255) * 100}%`;

  return (
    <View style={estilos.sliderRgbLinha}>
      <Text style={estilos.sliderRgbLabel}>{label}</Text>
      <View
        style={estilos.sliderRgbArea}
        onLayout={event => setLargura(Math.max(1, event.nativeEvent.layout.width))}
        {...panResponder.panHandlers}
      >
        <LinearGradient
          colors={['#000000', corFinal]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 0 }}
          style={estilos.sliderRgbBarra}
        />
        <View style={[estilos.sliderRgbMarcador, { left: posicao }]} />
      </View>
      <TextInput
        style={estilos.inputRgb}
        value={String(limitarCanal(valor))}
        keyboardType="number-pad"
        maxLength={3}
        selectTextOnFocus
        onChangeText={texto => onChange(limitarCanal(Number(texto.replace(/\D/g, ''))))}
      />
    </View>
  );
}

function NeumorphicButton({ children, onPress, style }: any) {
  const scale = React.useRef(new Animated.Value(1)).current;

  const handlePressIn = () => {
    Animated.spring(scale, { 
      toValue: 0.95, 
      useNativeDriver: true, 
      speed: 50, 
      bounciness: 0 
    }).start();
  };

  const handlePressOut = () => {
    Animated.spring(scale, { 
      toValue: 1, 
      useNativeDriver: true, 
      speed: 40, 
      bounciness: 4 
    }).start();
  };

  return (
    <TouchableWithoutFeedback onPressIn={handlePressIn} onPressOut={handlePressOut} onPress={onPress}>
      <Animated.View style={[{ transform: [{ scale }] }, style]}>
        <LinearGradient
          colors={COR_BORDA_GRAD}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={estilos.cardBordaGrad}
        >
          {children}
        </LinearGradient>
      </Animated.View>
    </TouchableWithoutFeedback>
  );
}

